+/**
+ * A text file based implementation of a {@link ViolationStore}.<br>
+ * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
+ * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
+ *
+ * <p>By default, the layout within the configured store folder will look like:</p>
+ * <pre><code>
+ * storeFolder
+ *   |-- stored.rules (the index file of all stored rules)
+ *   |-- 6fc2fd04-b3ab-44e0-8f78-215c66f2174a (a rule violation file named randomly by UUID and referenced from stored.rules)
+ *   |-- ... (more rule violation files for every rule that has been stored so far)
+ * </code></pre>
+ *
+ * <p>This {@link ViolationStore} can be configured through the following properties:</p>
+ * <pre><code>
+ * default.path=...               # string: the path of the folder where violation files will be stored
+ * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
+ * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
+ * default.fileNames=random       # random, description, or a RuleViolationFileNameStrategy class name
+ * default.integrity=ignore       # repair, fail, or ignore
+ * </code></pre>
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final Pattern DESCRIPTION_WORD = Pattern.compile("(?<![A-Za-z0-9])[A-Za-z0-9]{4,120}(?![A-Za-z0-9])");
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String FILE_NAMES_DEFAULT = "random";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_DEFAULT = "ignore";
+
+    /*
+     * The lock is deliberately shared by all store instances in this VM. In particular, an integrity scan must not
+     * race a save from another TextFileBasedViolationStore instance.
+     */
+    private static final ConcurrentHashMap<String, StoreState> STORE_STATES = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+    private final boolean strategyGivenToConstructor;
+
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private File storeFolder;
+    private StoreState storedRules;
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+    private boolean canDeriveExistingFileNames;
+    private IntegrityMode integrityMode;
+
+    /**
+     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
+     *
+     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
+     */
+    public TextFileBasedViolationStore() {
+        this(null, false);
+    }
+
+    /**
+     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        this(ruleViolationFileNameStrategy, true);
+    }
+
+    private TextFileBasedViolationStore(RuleViolationFileNameStrategy strategy, boolean strategyGivenToConstructor) {
+        if (strategyGivenToConstructor) {
+            this.constructorStrategy = checkNotNull(strategy);
+        } else {
+            this.constructorStrategy = description -> UUID.randomUUID().toString();
+        }
+        this.strategyGivenToConstructor = strategyGivenToConstructor;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        checkNotNull(properties);
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(
+                ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(
+                ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
+        configureFileNameStrategy(properties);
+
+        File configuredStoreFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
+        File configuredStoredRulesFile = new File(configuredStoreFolder, STORED_RULES_FILE_NAME);
+        prepareFolderAndIndex(configuredStoreFolder, configuredStoredRulesFile);
+
+        try {
+            storeFolder = configuredStoreFolder.getCanonicalFile();
+            File storedRulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
+            StoreState state = getStoreState(storedRulesFile);
+            synchronized (state) {
+                boolean indexExists = existsWithoutFollowingLinks(storedRulesFile.toPath());
+                Properties rules = indexExists ? loadRulesFrom(storedRulesFile) : new Properties();
+                IntegrityReport report = integrityMode == IntegrityMode.IGNORE
+                        ? IntegrityReport.empty()
+                        : inspect(rules);
+
+                if (integrityMode == IntegrityMode.FAIL && report.hasIssues()) {
+                    throw new StoreInitializationFailedException(report.failureMessage(storedRulesFile));
+                }
+
+                boolean changed = integrityMode == IntegrityMode.REPAIR && repair(rules, report);
+                if (!indexExists || changed) {
+                    writeRulesAtomically(storedRulesFile.toPath(), rules);
+                }
+                state.replace(rules);
+                storedRules = state;
+            }
+            log.trace("Initialized {} at {}", TextFileBasedViolationStore.class.getSimpleName(),
+                    new File(storeFolder, STORED_RULES_FILE_NAME).getAbsolutePath());
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void configureFileNameStrategy(Properties properties) {
+        if (strategyGivenToConstructor) {
+            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Property '%s' cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            ruleViolationFileNameStrategy = constructorStrategy;
+            canDeriveExistingFileNames = true;
+            return;
+        }
+
+        String configuredStrategy = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_DEFAULT);
+        if ("random".equals(configuredStrategy)) {
+            ruleViolationFileNameStrategy = constructorStrategy;
+            canDeriveExistingFileNames = false;
+        } else if ("description".equals(configuredStrategy)) {
+            ruleViolationFileNameStrategy = TextFileBasedViolationStore::descriptionFileName;
+            canDeriveExistingFileNames = true;
+        } else {
+            ruleViolationFileNameStrategy = loadFileNameStrategy(configuredStrategy);
+            canDeriveExistingFileNames = true;
+        }
+    }
+
+    private RuleViolationFileNameStrategy loadFileNameStrategy(String className) {
+        try {
+            Class<?> strategyClass = Class.forName(className);
+            if (!Modifier.isPublic(strategyClass.getModifiers())) {
+                throw new StoreInitializationFailedException(String.format(
+                        "RuleViolationFileNameStrategy '%s' must be public and have a public no-argument constructor", className));
+            }
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Configured file name strategy '%s' does not implement %s", className,
+                        RuleViolationFileNameStrategy.class.getName()));
+            }
+            Constructor<?> constructor = strategyClass.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
+                 InvocationTargetException | ClassCastException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot instantiate RuleViolationFileNameStrategy '%s'; it must be public and have a public no-argument constructor",
+                    className), e);
+        }
+    }
+
+    private void prepareFolderAndIndex(File configuredStoreFolder, File configuredStoredRulesFile) {
+        Path folder = configuredStoreFolder.toPath();
+        Path index = configuredStoredRulesFile.toPath();
+        boolean indexExists = existsWithoutFollowingLinks(index);
+
+        if (!indexExists && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+
+        try {
+            if (!Files.exists(folder, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
+                if (!configuredStoreFolder.mkdirs() && !Files.isDirectory(folder, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
+                    throw new StoreInitializationFailedException(String.format(
+                            "Cannot create rule store folder %s", configuredStoreFolder.getAbsolutePath()));
+                }
+            }
+            if (!Files.isDirectory(folder, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Rule store path is not a directory: %s", configuredStoreFolder.getAbsolutePath()));
+            }
+            if (indexExists && !isRegularFileDirectlyInFolder(index, folder)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Rule store index is not a regular file directly in %s: %s",
+                        configuredStoreFolder.getAbsolutePath(), configuredStoredRulesFile.getAbsolutePath()));
+            }
+        } catch (InvalidPathException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private StoreState getStoreState(File storedRulesFile) throws IOException {
+        String key = storedRulesFile.getCanonicalPath();
+        return STORE_STATES.computeIfAbsent(key, ignored -> new StoreState(storedRulesFile));
+    }
+
+    private static boolean existsWithoutFollowingLinks(Path path) {
+        return Files.exists(path, java.nio.file.LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private static boolean isRegularFileDirectlyInFolder(Path file, Path folder) throws IOException {
+        if (!Files.isRegularFile(file, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
+            return false;
+        }
+        return file.toAbsolutePath().normalize().getParent().equals(folder.toAbsolutePath().normalize());
+    }
+
+    private Properties loadRulesFrom(File file) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(file)) {
+            result.load(inputStream);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        return result;
+    }
+
+    private void checkInitialized() {
+        if (storedRules == null) {
+            throw new IllegalStateException("Violation store has not been initialized");
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        checkInitialized();
+        synchronized (storedRules) {
+            return storedRules.properties().containsKey(normalize(rule.getDescription()));
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        checkInitialized();
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storedRules) {
+            String description = normalize(rule.getDescription());
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                forgetRule(description);
+            } else if (!violations.isEmpty()) {
+                storeViolations(description, violations);
+            } else {
+                storeViolations(description, violations);
+            }
+        }
+    }
+
+    private void storeViolations(String description, List<String> violations) {
+        Properties current = storedRules.properties();
+        String recordedFileName = current.getProperty(description);
+        if (recordedFileName == null) {
+            String newFileName = createFileName(description);
+            Path destination = validateNewFileDestination(newFileName, current);
+            writeViolationFile(destination, violations);
+
+            Properties updated = copyOf(current);
+            updated.setProperty(description, normalize(newFileName));
+            try {
+                writeRulesAtomically(storedRules.file().toPath(), updated);
+            } catch (RuntimeException e) {
+                deleteIfExists(destination);
+                throw e;
+            }
+            storedRules.replace(updated);
+        } else {
+            Path destination = validateExistingFileDestination(recordedFileName);
+            writeViolationFile(destination, violations);
+        }
+    }
+
+    private void forgetRule(String description) {
+        Properties current = storedRules.properties();
+        String recordedFileName = current.getProperty(description);
+        if (recordedFileName == null) {
+            return;
+        }
+
+        IntegrityReport report = inspect(current);
+        Entry entry = report.entryFor(description);
+        if (entry == null) {
+            return;
+        }
+        if (!entry.shared && entry.resolvedPath != null) {
+            deleteEntryFile(entry);
+        }
+
+        Properties updated = copyOf(current);
+        updated.remove(description);
+        try {
+            writeRulesAtomically(storedRules.file().toPath(), updated);
+        } catch (RuntimeException e) {
+            throw e;
+        }
+        storedRules.replace(updated);
+    }
+
+    private String createFileName(String description) {
+        String result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (result == null || result.isEmpty()) {
+            throw new StoreUpdateFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no file name for rule '%s'", description));
+        }
+        return result;
+    }
+
+    private Path validateNewFileDestination(String fileName, Properties current) {
+        Path destination = pathForFileName(fileName);
+        if (STORED_RULES_FILE_NAME.equals(fileName) || isSamePath(destination, storedRules.file().toPath())) {
+            throw new StoreUpdateFailedException("A rule violation file cannot be named " + STORED_RULES_FILE_NAME);
+        }
+        for (String recorded : current.stringPropertyNames()) {
+            if (fileName.equals(current.getProperty(recorded))) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Rule violation file '%s' is already recorded by another rule", fileName));
+            }
+        }
+        ensureDirectDestination(destination, false, "new rule violation file");
+        if (existsWithoutFollowingLinks(destination)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to overwrite unowned rule violation file '%s'", fileName));
+        }
+        return destination;
+    }
+
+    private Path validateExistingFileDestination(String fileName) {
+        Path recordedPath = pathForFileName(fileName);
+        if (STORED_RULES_FILE_NAME.equals(fileName) || isSamePath(recordedPath, storedRules.file().toPath())) {
+            throw new StoreUpdateFailedException("Refusing to overwrite " + STORED_RULES_FILE_NAME);
+        }
+        ensureDirectDestination(recordedPath, true, "stored rule violation file");
+        try {
+            if (existsWithoutFollowingLinks(recordedPath)) {
+                return recordedPath.toRealPath();
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+        return recordedPath;
+    }
+
+    private void ensureDirectDestination(Path destination, boolean mayExist, String what) {
+        try {
+            Path folder = storeFolder.toPath().toRealPath();
+            Path normalized = destination.toAbsolutePath().normalize();
+            if (!folder.equals(normalized.getParent())) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to write %s outside the store folder: %s", what, destination));
+            }
+            if (existsWithoutFollowingLinks(destination)) {
+                Path real = destination.toRealPath();
+                if (!folder.equals(real.getParent()) || (!mayExist && !Files.isRegularFile(real))) {
+                    throw new StoreUpdateFailedException(String.format(
+                            "Refusing to write %s outside the store folder: %s", what, destination));
+                }
+            } else if (!folder.equals(destination.getParent().toRealPath())) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to write %s outside the store folder: %s", what, destination));
+            }
+        } catch (IOException | InvalidPathException e) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot safely resolve %s: %s", what, destination));
+        }
+    }
+
+    private Path pathForFileName(String fileName) {
+        try {
+            return storeFolder.toPath().resolve(fileName);
+        } catch (InvalidPathException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void writeViolationFile(Path destination, List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+
+        Path temporaryFile = null;
+        try {
+            temporaryFile = Files.createTempFile(storeFolder.toPath(), ".violation-", ".tmp");
+            Files.write(temporaryFile, builder.toString().getBytes(UTF_8), StandardOpenOption.TRUNCATE_EXISTING);
+            moveReplacing(temporaryFile, destination);
+            temporaryFile = null;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            deleteIfExists(temporaryFile);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        checkInitialized();
+        synchronized (storedRules) {
+            String ruleDetailsFileName = storedRules.properties().getProperty(normalize(rule.getDescription()));
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        try {
+            String violationsText = new String(Files.readAllBytes(pathForFileName(ruleDetailsFileName)), UTF_8);
+            if (isOnlyLineBreaks(violationsText)) {
+                return Collections.emptyList();
+            }
+
+            List<String> result = new ArrayList<>();
+            StringBuilder current = new StringBuilder();
+            for (int i = 0; i < violationsText.length(); i++) {
+                char character = violationsText.charAt(i);
+                if (character == '\n' && (current.length() == 0 || current.charAt(current.length() - 1) != '\\')) {
+                    addReadLine(result, current);
+                    current.setLength(0);
+                } else {
+                    current.append(character);
+                }
+            }
+            addReadLine(result, current);
+            return result;
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private void addReadLine(List<String> result, StringBuilder line) {
+        if (line.length() > 0 && !(line.length() == 1 && line.charAt(0) == '\r')) {
+            result.add(unescape(line.toString()));
+        }
+    }
+
+    private boolean isOnlyLineBreaks(String text) {
+        if (text.isEmpty()) {
+            return true;
+        }
+        for (int i = 0; i < text.length(); i++) {
+            if (text.charAt(i) != '\n' && text.charAt(i) != '\r') {
+                return false;
+            }
